-- =============================================================================
-- step-ap1-casement-templates.sql  (Step AP item 1)
-- Three casement drawing templates, in a "Casement" group on the casement
-- profile, so surveyors can start a casement or direct glazed drawing.
--
-- Written by Claude for Nathan to run in the Supabase SQL editor.
-- Run AFTER sql/step-ap0-gearbox-part-costs.sql (the reviewer's file).
-- Safe to run twice: each template is inserted only if its name is absent.
--
-- The trees below were GENERATED by the board's own code
-- (src/drawingBoard/casementOpenings.js buildCasementFrame), from the
-- casement profile's values, so a template is exactly what the board makes:
--   frame 1200 x 1300 (surveyors resize), jambs 37, head and cill 47,
--   depth 96, stops 20, cill 47 x 128, solid mullion 27 at its LEFT face,
--   casement sash 54 thick with 62 head and stiles, 83 bottom rail and 4
--   clearance, sash glass rebate 16 / tolerance 2, direct glazed unit with
--   20 clearance, rebate 20 / tolerance 2 and 18 of glass hidden in the
--   rebate stored on the unit.
--   typeOfWork complete_new; softwood / softwood / utile ("Softwood with
--   Hardwood Cill"); sash type open_out; glass by PART CODE (GL100010 /
--   GL100080), which is what the Step AE glass-code guard requires;
--   Casement MPLS on by default; and NO stored ironmongery list, so
--   Integrate's own default_ironmongery rules price the ironmongery and
--   follow the openings (Step AP item 5).
-- =============================================================================

BEGIN;

-- The casement profile (code 'casement'); every template points at it.
DO $$
DECLARE _profile_id uuid;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles WHERE code = 'casement' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''casement'' — the casement profile must exist first';
  END IF;

  -- Single Flush Casement
  IF NOT EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = 'Single Flush Casement') THEN
    INSERT INTO public.drawing_templates
      (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
    VALUES (
      'Single Flush Casement', 'casement', 'Casement', 'Casement',
      _profile_id,
      '{"key":"drawingItem_1","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile"},"children":[{"key":"paintAndIronmongery_2","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_3","part_type":"notesPart","values":{},"children":[]},{"key":"price_4","part_type":"pricePart","values":{},"children":[]},{"key":"assemblyFrame_5","part_type":"assemblyFramePart","values":{"width":1200,"height":1300,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"casementSash_6","part_type":"casementSashPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","sashThickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_7","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"cill_8","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}'::jsonb,
      10, TRUE
    );
  END IF;

  -- Double Flush Casement
  IF NOT EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = 'Double Flush Casement') THEN
    INSERT INTO public.drawing_templates
      (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
    VALUES (
      'Double Flush Casement', 'casement', 'Casement', 'Casement',
      _profile_id,
      '{"key":"drawingItem_1","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile"},"children":[{"key":"paintAndIronmongery_2","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_3","part_type":"notesPart","values":{},"children":[]},{"key":"price_4","part_type":"pricePart","values":{},"children":[]},{"key":"assemblyFrame_5","part_type":"assemblyFramePart","values":{"width":1200,"height":1300,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"mullion_6","part_type":"mullionPart","values":{"offset":549.5,"thicknessInFrame":27,"mullionStopSize":20},"children":[]},{"key":"casementSash_7","part_type":"casementSashPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","sashThickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_8","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"casementSash_9","part_type":"casementSashPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","sashThickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":83,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"glass_10","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"cill_11","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}'::jsonb,
      20, TRUE
    );
  END IF;

  -- Direct Glazed Frame
  IF NOT EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = 'Direct Glazed Frame') THEN
    INSERT INTO public.drawing_templates
      (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
    VALUES (
      'Direct Glazed Frame', 'casement', 'Casement', 'Casement',
      _profile_id,
      '{"key":"drawingItem_1","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile"},"children":[{"key":"paintAndIronmongery_2","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_3","part_type":"notesPart","values":{},"children":[]},{"key":"price_4","part_type":"pricePart","values":{},"children":[]},{"key":"assemblyFrame_5","part_type":"assemblyFramePart","values":{"width":1200,"height":1300,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"glass_6","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","toBeReplaced":true,"mechanicalClearanceLeft":20,"mechanicalClearanceRight":20,"mechanicalClearanceTop":20,"mechanicalClearanceBottom":20,"hiddenInRebateLeft":18,"hiddenInRebateRight":18,"hiddenInRebateTop":18,"hiddenInRebateBottom":18,"glazingRebateWidth":20,"glazingTolerance":2},"children":[]},{"key":"cill_7","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}'::jsonb,
      30, TRUE
    );
  END IF;
END $$;

COMMIT;

-- CHECK: three casement templates, each on the casement profile, each tree
-- holding its openings. Expect 3 rows: Single (1 casement sash, 0 mullions),
-- Double (2 sashes, 1 mullion), Direct Glazed (0 sashes, 1 direct glazed).
SELECT t.name, t.family, t.group_name, t.sort_order, p.code AS profile,
       jsonb_array_length(t.tree -> 'children') AS top_level_children,
       (SELECT count(*) FROM jsonb_array_elements(
          (SELECT c FROM jsonb_array_elements(t.tree -> 'children') c
            WHERE c ->> 'part_type' = 'assemblyFramePart') -> 'children') f
        WHERE f ->> 'part_type' = 'casementSashPart') AS casement_sashes,
       (SELECT count(*) FROM jsonb_array_elements(
          (SELECT c FROM jsonb_array_elements(t.tree -> 'children') c
            WHERE c ->> 'part_type' = 'assemblyFramePart') -> 'children') f
        WHERE f ->> 'part_type' = 'glassPart') AS direct_glazed_units,
       (SELECT count(*) FROM jsonb_array_elements(
          (SELECT c FROM jsonb_array_elements(t.tree -> 'children') c
            WHERE c ->> 'part_type' = 'assemblyFramePart') -> 'children') f
        WHERE f ->> 'part_type' = 'mullionPart') AS mullions
FROM public.drawing_templates t
LEFT JOIN public.default_profiles p ON p.id = t.default_profile_id
WHERE t.family = 'casement'
ORDER BY t.sort_order;

